package es.riegocerca.maps; import android.app.Activity; import android.content.*; import android.net.Uri; import android.webkit.JavascriptInterface; import android.widget.Toast;
public class MapsBridge{private final Activity a;public MapsBridge(Activity a){this.a=a;}@JavascriptInterface public void navigate(double lat,double lon){if(!Double.isFinite(lat)||!Double.isFinite(lon)||lat<-90||lat>90||lon<-180||lon>180){a.runOnUiThread(()->Toast.makeText(a,"Coordenadas GPS no válidas",Toast.LENGTH_LONG).show());return;}a.runOnUiThread(()->{Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse("google.navigation:q="+lat+","+lon+"&mode=d"));i.setPackage("com.google.android.apps.maps");try{a.startActivity(i);}catch(ActivityNotFoundException e){try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.google.com/maps/dir/?api=1&destination="+lat+","+lon+"&travelmode=driving")));}catch(Exception x){Toast.makeText(a,"No se pudo abrir Google Maps",Toast.LENGTH_LONG).show();}}});}}
